// === Tab: mySketch ===
let aryColors = [];
let radRate;
let aryCircles = [];

function setup() {
  aryColors = [color("#5CE5D3"),
              color("#F6978D"), 
              color("#833F72"),
              color("#472261"),
              color("#10175B")];
  let canvasSize;
  if (windowWidth <= windowHeight) {
    canvasSize = windowWidth;
  } else {
    canvasSize = windowHeight;
  }
  createCanvas(canvasSize, canvasSize)
  background(aryColors[4]);
  strokeWeight(width/500);
  noFill();
  radRate = PI/10; //B
}

function draw() {
  for (i=0; i<aryCircles.length; i++) {
    aryCircles[i].updateMe();
  }
}

function mouseClicked() {
  let newCircle;
  newCircle = new Circle();
  aryCircles.push(newCircle);
}

class Circle {
  constructor() {
    this.endX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
    this.endY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
    this.radNew = (int(random(1, 4))) * PI / 2;
    this.direction = true;
    this.radPrev = this.radNew;
    this.radCurrent = this.radNew;
    stroke(aryColors[0]);
  }

  updateMe() {
    if ((this.direction == true && this.radCurrent >= this.radNew) ||
        (this.direction == false && this.radCurrent <= this.radNew)) {
      this.radShift = random([0, PI]);
      if (this.radShift == PI) {
        this.direction = ! this.direction;
      }
      this.radPrev = (this.radNew + this.radShift) % (PI * 2);
      this.radius = width / 10 * random(0.1, 0.4); //B
      this.centX = this.endX - this.radius * cos(this.radPrev);
      this.centY = this.endY - this.radius * sin(this.radPrev);
      if (this.direction == true) {
        this.radNew = this.radPrev + (int(random(1, 3))) * PI / 2; //90~270deg
      } else {
        this.radNew = this.radPrev - (int(random(1, 3))) * PI / 2; //-90~-270deg
      }
      this.radCurrent = this.radPrev;
    }

    if (this.direction == true) {
      if (this.radCurrent + radRate < this.radNew) {
        arc(this.centX, this.centY,
          this.radius*2, this.radius*2,
          this.radCurrent, this.radCurrent + radRate);
        this.radCurrent = this.radCurrent + radRate;
      } else {
        arc(this.centX, this.centY,
          this.radius*2, this.radius*2,
          this.radCurrent, this.radNew);
        this.radCurrent = this.radNew;
        this.endX = this.centX + this.radius * cos(this.radNew);
        this.endY = this.centY + this.radius * sin(this.radNew);
      }
    } else {
      if (this.radCurrent - radRate > this.radNew) {
        arc(this.centX, this.centY,
          this.radius*2, this.radius*2,
          this.radCurrent - radRate, this.radCurrent);
        this.radCurrent = this.radCurrent - radRate;
      } else {
        arc(this.centX, this.centY,
          this.radius*2, this.radius*2,
          this.radNew, this.radCurrent);
        this.radCurrent = this.radNew;
        this.endX = this.centX + this.radius * cos(this.radNew);
        this.endY = this.centY + this.radius * sin(this.radNew);
      }
    }
  }
}

